// spec: specs/hal-engine-tool-input-validation/spec.md#3
it('rejects wrong types with a safe field path and expected type', async () => {
  const registry = new ToolRegistry();
  let calls = 0;
  registry.register(
    {
      name: 'get_weather',
      description: 'Weather for a location',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}},
    },
    async () => {
      calls += 1;
      return 'sunny';
    }
  );

  const response = await registry.execute('get_weather', {location: 987654321});

  expect(response.result).toMatch(/location.*string/);
  expect(response.result).not.toContain('987654321');
  expect(calls).toBe(0);
});
EOF
